from lib import *
r=[]
r.append(R(6938246,"टर्की भरे पोर्टोबेलो मशरूम, फ़ेटा, पालक और पेकान सलाद के साथ","ताज़गी भरे सलाद के साथ परोसे गए हमारे मधुमेह के अनुकूल भरवाँ मशरूम के साथ मौसम के भरपूर स्वादों का आनंद लें। यह बहुत कम कार्बोहाइड्रेट भोजन पैटर्न वाला व्यंजन स्वादिष्ट और पोषक तत्वों से भरपूर है, जो इसे सेहतमंद भोजन के लिए बढ़िया विकल्प बनाता है।","4","1 भरा मशरूम, 2 कप सलाद",
["4 बड़े पोर्टोबेलो मशरूम (सिर्फ़ टोपियाँ)","1 पाउंड कम वसा वाली कीमा टर्की (99% कम वसा)","1 छोटा प्याज़ (बारीक कटा हुआ)","2 फाँक लहसुन (बारीक कटा हुआ)","7 1/2 औंस कटे हुए टमाटर (बिना नमक मिलाए, डिब्बाबंद हों तो पानी निथारे हुए)","1/2 छोटा चम्मच सूखा अजवायन","1/2 छोटा चम्मच स्मोक्ड पेपरिका","1/4 छोटा चम्मच काली मिर्च","1 स्प्रे जैतून का तेल","5 औंस बेबी पालक","1/4 कप कम वसा वाला फ़ेटा चीज़ (चूरा किया हुआ)","1/4 कप पेकान (कटे हुए)","1/2 साबुत इंग्लिश खीरा (पतला कटा हुआ)","1 कप चेरी टमाटर (आधे कटे हुए)","2 बड़े चम्मच बालसमिक सिरका","1 बड़ा चम्मच जैतून का तेल","1 छोटा चम्मच डिजॉन सरसों"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","पोर्टोबेलो मशरूम की टोपियों से डंठल हटाएँ और नीचे की पतली परतें खुरच दें। टोपियों पर हल्का सा जैतून के तेल का स्प्रे करें और उन्हें खुला हिस्सा ऊपर करके बेकिंग शीट पर रखें।","एक नॉन-स्टिक कड़ाही को मध्यम आँच पर गरम करें। कीमा टर्की और कटा प्याज़ डालें। टर्की को तोड़ते हुए, गुलाबी रंग न रहने तक पकाएँ (लगभग 5–6 मिनट)। बारीक कटा लहसुन डालें और 1 मिनट और पकाएँ।","कटे टमाटर, अजवायन, स्मोक्ड पेपरिका, नमक और काली मिर्च डालकर चलाएँ। अच्छी तरह मिलाएँ और 3–4 मिनट और पकाएँ।","टर्की के मिश्रण को मशरूम की टोपियों में बराबर बाँटें। 15–20 मिनट तक या मशरूम के नरम होने और भरावन के गरम होने तक बेक करें।","एक बड़े कटोरे में बेबी पालक, चूरा किया फ़ेटा, भुने हुए पेकान, खीरा और चेरी टमाटर मिलाएँ।","एक छोटे कटोरे में बालसमिक सिरका, जैतून का तेल और डिजॉन सरसों को फेंटें। ड्रेसिंग को सलाद पर डालें और समान रूप से लपेटने के लिए मिलाएँ।","एक भरी हुई मशरूम की टोपी को साइड में सलाद के साथ परोसें।"]))
r.append(R(6938670,"टर्की स्ट्रोगनॉफ़","थैंक्सगिविंग के दिन पूरी टर्की खाने की ज़रूरत नहीं है! इस जैसी दूसरी रेसिपी में इस्तेमाल करने के लिए कुछ बचा हुआ रख लें। अपने मधुमेह प्रबंधन के हिस्से के रूप में अपनी मात्रा पर नज़र रखते हुए नए भोजन पाएँ!","6","3 औंस टर्की + 2/3 कप मशरूम और नूडल्स का मिश्रण",
["6 औंस एग नूडल्स","2 छोटे चम्मच खसखस","18 औंस टर्की ब्रेस्ट (ताज़ा रोस्ट किया हुआ, 2 x 1/2 इंच की पट्टियों में कटा हुआ)","1/8 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच ताज़ी पिसी काली मिर्च","2 साबुत पोर्टोबेलो मशरूम (हर एक 4 औंस)","1 छोटा पीला प्याज़ (पतला कटा हुआ)","1 बड़ा चम्मच मक्खन","1 1/2 बड़े चम्मच मैदा (सर्व-उपयोगी आटा)","1 1/2 कप बीफ़ ब्रॉथ (कम सोडियम वाला)","1/2 कप सादा वसा रहित ग्रीक दही","1 1/2 छोटा चम्मच डिजॉन सरसों"],
["पैकेट पर दिए निर्देशों के अनुसार नूडल्स पकाएँ। नूडल्स को खसखस के साथ मिलाएँ और गरम रखने के लिए खाली पकाने वाले बरतन में वापस रख दें। टर्की की पट्टियों पर नमक और काली मिर्च छिड़कें; लपेटने के लिए मिलाएँ। मशरूम के डंठल हटाकर फेंक दें। मशरूम की टोपियों को चार भागों में काटें और पतला काट लें।","इस बीच, एक बड़ी नॉनस्टिक कड़ाही पर नॉनस्टिक कुकिंग स्प्रे हल्का सा लगाएँ और मध्यम-तेज़ आँच पर रखें। प्याज़ को 2 मिनट भूनें। मशरूम डालें और मशरूम के नरम होने तक, लगभग 5-6 मिनट, भूनें। एक बड़े कटोरे में निकाल लें।","कड़ाही में मध्यम आँच पर मक्खन पिघलाएँ। मैदा डालें और लगातार चलाते हुए 1 मिनट पकाएँ। धीरे-धीरे ब्रॉथ फेंटकर मिलाएँ। लकड़ी के चम्मच से चलाते हुए, सॉस के गाढ़ा होने और उबलने तक, लगभग 4 मिनट, पकाएँ।","आँच धीमी करें। ग्रीक दही और सरसों फेंटकर मिलाएँ। टर्की और अलग रखी सब्ज़ियाँ, जमा हुए रस के साथ, कड़ाही में वापस डालें। गरम होने तक पकाएँ (उबालें नहीं)। नूडल्स को प्लेटों में बाँटें और ऊपर से स्ट्रोगनॉफ़ चम्मच से डालें।"]))
r.append(R(6942512,"ब्रोकली चीज़ बाइट्स","ये बाइट्स बढ़िया स्नैक या स्टार्टर हैं, और आपकी सेहतमंद खान-पान योजना में ज़्यादा सब्ज़ियाँ जोड़ने का उत्कृष्ट तरीका हैं।","6","5 टुकड़े",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 गुच्छे ब्रोकली (किनारे कटे हुए)","1 बड़ा अंडा","1 बड़े अंडे की सफ़ेदी","1/3 कप कम वसा वाला कद्दूकस किया चेडर या मैक्सिकन शैली का चीज़","1/3 कप ब्रेड क्रम्ब्स","1/2 कप प्याज़ (कटा हुआ)","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। एक बड़ी (या दो छोटी) बेकिंग शीट पर कुकिंग स्प्रे लगाएँ। एक तरफ़ रख दें।","ब्रोकली को लगभग 10 से 12 मिनट, नरम होने तक, भाप में पकाएँ। ठंडा होने के लिए (लगभग 10 मिनट) एक तरफ़ रख दें।","ब्रोकली और बाकी सामग्री को ब्लेंडर या फ़ूड प्रोसेसर में डालें और मिलाने के लिए पल्स करें। ज़्यादा न मिलाएँ; मिश्रण थोड़ा दरदरा होना चाहिए, पेस्ट नहीं। मिश्रण को 10 मिनट रहने दें।","मिश्रण को रहने देने के बाद, उसे चलाएँ, और बड़े चम्मच भर-भर कर तैयार बेकिंग शीट पर डालें।","हर गोले के ऊपर हल्का सा कुकिंग स्प्रे करें। 15 मिनट बेक करें। टुकड़ों को पलटें और 10 मिनट और बेक करें, या सुनहरा भूरा होने तक।"]))
r.append(R(6942698,"पालक और संतरा सलाद","यह ताज़ा सलाद साल के किसी भी समय एकदम बढ़िया लगेगा, लेकिन पतझड़ या सर्दियों में ख़ासकर स्वागत योग्य हो सकता है, जब साइट्रस फल ज़्यादा मिलते हैं और दूसरी सब्ज़ियाँ कम होती हैं।","2","1 कप सलाद, 2 बड़े चम्मच ड्रेसिंग के साथ",
["1 कप बेबी पालक","2 बड़े चम्मच सेलेरी (कटी हुई)","2 छोटे सफ़ेद (बटन) मशरूम (कटे हुए)","1 मध्यम लाल प्याज़ (आधा काटकर छल्लों में अलग किया हुआ)","1/2 मध्यम संतरा (छिला और फाँकों में अलग किया हुआ)","2 बड़े चम्मच संतरे का रस","1 बड़ा चम्मच नीबू का रस","1 छोटा चम्मच जैतून का तेल","1 छोटा चम्मच कम सोडियम वाला सोया सॉस","1 छोटा चम्मच शहद","1/8 छोटा चम्मच पिसी अदरक","1/8 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच पेपिटास (कद्दू के बीज)"],
["एक मध्यम सलाद बाउल में पालक, सेलेरी, मशरूम, प्याज़ और संतरे की फाँकों को मिलाएँ।","एक छोटे कटोरे में कद्दू के बीज को छोड़कर बाकी सामग्री फेंटें। सलाद पर डालें। मिलाने के लिए हिलाएँ। कद्दू के बीज से सजाएँ।"]))
r.append(R(6942750,"कम सोडियम वाली टर्की","कम सोडियम वाली टर्की की पोषण संबंधी जानकारी","1","3 औंस",["3 औंस कम सोडियम वाली टर्की"],[]))
r.append(R(6942761,"हरे प्याज़ के साथ सादा ब्राउन राइस","सोया सॉस और राइस विनेगर के स्वादिष्ट मिश्रण के साथ ब्राउन राइस का स्वाद बढ़ाएँ, साथ ही रंग की झलक और ताज़े स्वाद के लिए हरे प्याज़ (या दूसरी जड़ी-बूटियाँ) डालें।","6","1/2 कप",
["5 डंठल हरा प्याज़ (पतला कटा हुआ)","1/4 छोटा चम्मच पिसी अदरक","1 बड़ा चम्मच राइस विनेगर","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच कम सोडियम वाला सोया सॉस","2 कप कम सोडियम वाला वेजिटेबल ब्रॉथ या पानी","1 कप ब्राउन राइस"],
["एक छोटे कटोरे में सोया सॉस, जैतून का तेल, राइस विनेगर और अदरक को फेंटें। सोया सॉस का मिश्रण चावल पर डालें और समान रूप से लपेटने के लिए मिलाएँ। हरा प्याज़ डालें और मिलाएँ।","एक सॉसपैन में तेज़ आँच पर चावल और ब्रॉथ को उबालें। आँच मध्यम-धीमी करें और चावल के नरम होने तक, लगभग 40 मिनट, धीमी आँच पर पकाएँ। (वैकल्पिक रूप से, आप चावल पकाने के लिए राइस कुकर का इस्तेमाल कर सकते हैं।) चावल को काँटे से फुलाएँ और एक बड़े कटोरे में रखें।"]))
r.append(R(6942919,"बटरनट स्क्वैश ग्रेटिन","यह भरपूर साइड डिश बेहद मलाईदार और संतोषजनक रूप से चीज़ी है, फिर भी 1 सर्विंग में 100 कैलोरी से कम है।","8","कैसरोल का 1/8 हिस्सा (3 1/4 x 4 1/2 इंच का आयत)",
["2 पाउंड बटरनट स्क्वैश","1 कप पानी","1 साबुत नॉनस्टिक कुकिंग स्प्रे","1 बड़ा चम्मच जैतून का तेल","2 बड़े चम्मच मैदा (सर्व-उपयोगी आटा)","2 कप हाफ़-एंड-हाफ़ (वसा रहित)","1/2 कप पारमेसन चीज़ (कद्दूकस किया हुआ, बाँटकर इस्तेमाल करें)","1/2 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ताज़ा थाइम (कटा हुआ)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। स्क्वैश को लंबाई में आधा काटें और 9x13 इंच की बेकिंग डिश में कटी तरफ़ नीचे करके रखें। स्क्वैश पर पानी डालें और 45 मिनट बेक करें।","स्क्वैश को पैन से निकालें और पानी निथार दें। बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","बीज निकालें और स्क्वैश का गूदा छिलके से चम्मच से निकालें। स्क्वैश का गूदा तैयार बेकिंग डिश में वापस डालें, उसे बराबर आकार के टुकड़ों में तोड़ते हुए।","एक सॉते पैन में मध्यम आँच पर तेल डालें। मैदा डालें और मिलाने के लिए चलाएँ। तेल और मैदे के मिश्रण को दो मिनट पकाएँ, फिर वसा रहित हाफ़-एंड-हाफ़ फेंटकर मिलाएँ। बार-बार फेंटते हुए उबाल आने दें।","1/4 कप पारमेसन चीज़, पिसी काली मिर्च और थाइम मिलाएँ। चीज़ के पिघलने तक चलाएँ।","सॉस को बटरनट स्क्वैश पर डालें और ऊपर से बचा हुआ 1/4 कप चीज़ छिड़कें। 25 मिनट या सुनहरा भूरा होने और बुलबुले उठने तक बेक करें।"]))
r.append(R(6944046,"दक्षिणी इतालवी बाक़ला प्यूरी (मक्कू)","मक्कू एमी रिओलो की पैतृक भूमि कैलाब्रिया, इटली में लोकप्रिय व्यंजन है। कैलाब्रिया शब्द एक बीज़ंटीन शब्द से निकला है जिसका अर्थ है “उपजाऊ भूमि”। यह क्षेत्र समृद्ध कृषि परंपराओं के साथ अपने नाम पर खरा उतरता है जो आज भी जारी हैं। मक्कू शब्द “मसले हुए” के लिए बोली के शब्द से आता है और बाक़ला से बनी प्यूरी को दर्शाता है, जो दुनिया की सबसे पुरानी कृषि फ़सलों में से एक है। सेंट जोसेफ़ दिवस पर कैलाब्रिया में ताज़े और सूखे बाक़ला के व्यंजन परोसे जाते हैं। इस स्टार्टर को अकेले, साइड डिश के रूप में जैतून का तेल डालकर, या क्रैकर्स, फ्लैटब्रेड, या काली मिर्च और सौंफ़ के बीजों वाले साबुत गेहूँ के क्रैकर रिंग्स के साथ परोसें। हो सके तो पहली कोल्ड-प्रेस्ड जैतून का तेल और पेकोरिनो क्रोटोनीज़ — कैलाब्रिया का उच्च गुणवत्ता वाला, पुराना भेड़ के दूध का चीज़ — इस्तेमाल करें। यह व्यंजन, कई लोकप्रिय इतालवी स्टार्टर्स की तरह, गरम या कमरे के तापमान पर परोसा जा सकता है। बाक़ला की जगह छोले और कैनेलिनी बीन्स इस्तेमाल किए जा सकते हैं।","6","1/3 कप",
["2/3 कप छिले हुए सूखे बाक़ला, उबलते पानी में 1 घंटे भिगोए और पानी निथारे हुए","1 छोटा प्याज़ (चार भागों में कटा हुआ)","1 तेज पत्ता","1/4 कप पेकोरिनो रोमानो चीज़","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर इस्तेमाल करें)","1 छोटा चम्मच सौंफ़ के बीज (सजाने के लिए थोड़े और)","1/8 छोटा चम्मच कुटी लाल मिर्च के गुच्छे","1/8 छोटा चम्मच अपरिष्कृत समुद्री नमक","1/4 छोटा चम्मच ताज़ी पिसी काली मिर्च"],
["बाक़ला, प्याज़ और तेज पत्ता एक बड़े सॉसपैन में रखें। पानी से ढककर तेज़ आँच पर उबालें। आँच मध्यम-धीमी करें, ढक दें और नरम होने तक, लगभग 1 घंटा, पकाएँ।","बाक़ला का पानी निथारें और चीज़, 1 बड़े चम्मच जैतून के तेल और सौंफ़ के बीजों के साथ फ़ूड प्रोसेसर में रखें। चिकना होने तक प्यूरी करें। चखें और कुटी लाल मिर्च के गुच्छे, नमक और काली मिर्च से स्वाद दें।","परोसने की थाली पर चम्मच से डालें और स्पैचुला से ऊपरी हिस्सा समतल करें। बचा हुआ 1 बड़ा चम्मच जैतून का तेल डालें, और चाहें तो ऊपर से कुटी लाल मिर्च के गुच्छे और सौंफ़ के बीज छिड़कें।"]))
r.append(R(6944484,"हल्की मरीनारा सॉस के साथ स्पैघेटी स्क्वैश","स्पैघेटी स्क्वैश पकाना आसान है और पास्ता का बढ़िया कम कार्बोहाइड्रेट वाला विकल्प बनता है। यह सर्दी के उस दिन के लिए एकदम सही है जब बच्चों की सर्दियों की छुट्टियों में स्कूल बंद हों।","6","रेसिपी का 1/6 हिस्सा",
["2 पाउंड मध्यम स्पैघेटी स्क्वैश (धोया हुआ)","2 बड़े चम्मच एक्स्ट्रा वर्जिन जैतून का तेल (बाँटकर इस्तेमाल करें)","14 मध्यम रोमा (प्लम) टमाटर (कटे हुए)","2 फाँक लहसुन (कटा हुआ)","1 मध्यम शैलट (बारीक कटा हुआ)","1/4 छोटा चम्मच काली मिर्च","1/2 छोटा चम्मच समुद्री नमक (बारीक)","1 कप ताज़ी तुलसी","3 बड़े चम्मच पारमेसन-रेजियानो चीज़ (बारीक कसा हुआ, बाँटकर इस्तेमाल करें)"],
["स्पैघेटी स्क्वैश में काँटे से कई जगह छेद करें और माइक्रोवेव में हाई पर रखें, जब तक छिलका नरम न हो जाए, लगभग 10-15 मिनट। ठंडा होने दें।","जब स्क्वैश पक रहा हो, तब एक मध्यम आकार के कटोरे में मरीनारा की सामग्री (1 बड़ा चम्मच जैतून का तेल, टमाटर, लहसुन, शैलट, काली मिर्च और नमक) मिलाएँ।","तुलसी की पत्तियाँ फाड़कर टमाटर के मिश्रण में डालें।","स्क्वैश को आधा काटें और \"स्पैघेटी\" बनाएँ। काँटे से \"स्पैघेटी\" के अलग-अलग रेशे निकालें। स्पैघेटी स्क्वैश को 1 बड़े चम्मच जैतून के तेल और 1 बड़े चम्मच पारमिजियानो-रेजियानो चीज़ के साथ मिलाएँ।","स्क्वैश को पाई प्लेट में रखें। ऊपर से हल्की मरीनारा और बचे हुए पारमिजियानो-रेजियानो चीज़ की छिड़कन (वैकल्पिक) डालें।","पके स्पैघेटी स्क्वैश के ऊपर परोसें।"]))
r.append(R(6945433,"क्रैनबेरी कद्दू मफ़िन","क्रैनबेरी कद्दू मफ़िन पतझड़ के स्वादों का आनंद लेने का बढ़िया तरीका है। हल्का मीठा कद्दू और खट्टी क्रैनबेरी इस मधुमेह के अनुकूल मफ़िन रेसिपी के लिए एकदम सही मेल हैं।","8","1 मफ़िन",
["1 कप बादाम का आटा","1/4 कप नारियल का आटा","1 छोटा चम्मच बेकिंग पाउडर","1/2 छोटा चम्मच पिसी दालचीनी","1/4 छोटा चम्मच पिसा जायफल","1/4 छोटा चम्मच पिसी अदरक","1/2 छोटा चम्मच नमक","1/2 कप कद्दू की प्यूरी (डिब्बाबंद)","1/4 कप बिना मीठा बादाम दूध","2 बड़े अंडे","1/2 कप बिना मीठा सेब की प्यूरी (एप्लसॉस)","2 बड़े चम्मच बादाम बटर","1/4 कप चीनी का विकल्प","1/2 कप क्रैनबेरी (ताज़ी या फ्रोज़न)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें। मफ़िन ट्रे में पेपर लाइनर लगाएँ।","एक बड़े कटोरे में बादाम का आटा, नारियल का आटा, बेकिंग पाउडर, दालचीनी, जायफल, अदरक और नमक फेंटकर मिलाएँ।","दूसरे कटोरे में कद्दू की प्यूरी, बादाम दूध, अंडे, सेब की प्यूरी, बादाम बटर और चीनी का विकल्प अच्छी तरह मिलने तक फेंटें।","गीली सामग्री को सूखी सामग्री में डालें और बस मिलने तक चलाएँ।","क्रैनबेरी को धीरे से मिलाएँ।","घोल को मफ़िन कप में समान रूप से चम्मच से डालें, हर एक को लगभग 2/3 भरें।","पहले से गरम ओवन में 18–20 मिनट बेक करें या जब तक बीच में डाला गया टूथपिक साफ़ न निकले।","मफ़िन को ट्रे में 5 मिनट ठंडा होने दें, फिर पूरी तरह ठंडा करने के लिए उन्हें वायर रैक पर रखें।"]))
save(7,r)
